import{_ as e,o as d,c as a,a0 as r}from"./chunks/framework.DCToIpx6.js";const m=JSON.parse('{"title":"REQ-DETAIL-PROP — Detail Property","description":"","frontmatter":{},"headers":[],"relativePath":"tests/test-cases/dynamic-column-config/REQ-DETAIL-PROP.md","filePath":"tests/test-cases/dynamic-column-config/REQ-DETAIL-PROP.md"}'),o={name:"tests/test-cases/dynamic-column-config/REQ-DETAIL-PROP.md"};function i(l,t,c,n,s,u){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="req-detail-prop-—-detail-property" tabindex="-1">REQ-DETAIL-PROP — Detail Property <a class="header-anchor" href="#req-detail-prop-—-detail-property" aria-label="Permalink to &quot;REQ-DETAIL-PROP — Detail Property&quot;">​</a></h1><p><strong>Requerimiento:</strong> Columnas PUEDEN especificar <code>detail: boolean</code> para marcarlas como portadoras de datos invisibles. Una columna con <code>detail: true</code> DEBE preservar su valor de fila para emisión al hacer clic en celda, incluso cuando <code>visible: false</code>.</p><hr><h2 id="tc-detail-prop-01-columna-detail-true-preserva-dato-invisible-en-click" tabindex="-1">TC-DETAIL-PROP-01: Columna detail:true preserva dato invisible en click <a class="header-anchor" href="#tc-detail-prop-01-columna-detail-true-preserva-dato-invisible-en-click" aria-label="Permalink to &quot;TC-DETAIL-PROP-01: Columna detail:true preserva dato invisible en click&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td><strong>ID</strong></td><td>TC-DETAIL-PROP-01</td></tr><tr><td><strong>Requerimiento</strong></td><td>REQ-DETAIL-PROP</td></tr><tr><td><strong>Prioridad</strong></td><td>Alta</td></tr><tr><td><strong>Tipo</strong></td><td>Funcional — Happy Path</td></tr><tr><td><strong>Precondiciones</strong></td><td>Columna <code>{key: &#39;id&#39;, header: &#39;ID&#39;, visible: false, detail: true}</code>. Columna clickeable: <code>{key: &#39;name&#39;, header: &#39;Name&#39;, clickeable: true}</code>. Fila: <code>{name: &#39;Alice&#39;, id: &#39;42&#39;}</code>.</td></tr><tr><td><strong>Pasos</strong></td><td>1. Hacer clic en celda &quot;Alice&quot;<br>2. Verificar payload de <code>cellClick</code></td></tr><tr><td><strong>Resultado Esperado</strong></td><td><code>cellClick.detailData</code> incluye <code>{label: &#39;ID&#39;, value: &#39;42&#39;}</code>. El valor <code>id: &#39;42&#39;</code> se preserva aunque la columna sea invisible.</td></tr></tbody></table><hr><h2 id="tc-detail-prop-02-columna-invisible-sin-detail-queda-excluida-de-emision" tabindex="-1">TC-DETAIL-PROP-02: Columna invisible sin detail queda excluida de emisión <a class="header-anchor" href="#tc-detail-prop-02-columna-invisible-sin-detail-queda-excluida-de-emision" aria-label="Permalink to &quot;TC-DETAIL-PROP-02: Columna invisible sin detail queda excluida de emisión&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td><strong>ID</strong></td><td>TC-DETAIL-PROP-02</td></tr><tr><td><strong>Requerimiento</strong></td><td>REQ-DETAIL-PROP</td></tr><tr><td><strong>Prioridad</strong></td><td>Alta</td></tr><tr><td><strong>Tipo</strong></td><td>Funcional — Happy Path (contraste)</td></tr><tr><td><strong>Precondiciones</strong></td><td>Columna <code>{key: &#39;secret&#39;, header: &#39;Secret&#39;, visible: false}</code> SIN <code>detail: true</code>. Fila: <code>{name: &#39;Alice&#39;, secret: &#39;classified&#39;}</code>.</td></tr><tr><td><strong>Pasos</strong></td><td>1. Hacer clic en celda clickeable de esa fila<br>2. Verificar payload de <code>cellClick</code></td></tr><tr><td><strong>Resultado Esperado</strong></td><td><code>secret</code> NO aparece en <code>detailData</code>. Solo columnas explícitamente <code>detail: true</code> son incluidas.</td></tr></tbody></table><hr><h2 id="tc-detail-prop-03-columna-detail-true-con-visible-true-se-renderiza-y-emite" tabindex="-1">TC-DETAIL-PROP-03: Columna detail:true con visible:true se renderiza Y emite <a class="header-anchor" href="#tc-detail-prop-03-columna-detail-true-con-visible-true-se-renderiza-y-emite" aria-label="Permalink to &quot;TC-DETAIL-PROP-03: Columna detail:true con visible:true se renderiza Y emite&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td><strong>ID</strong></td><td>TC-DETAIL-PROP-03</td></tr><tr><td><strong>Requerimiento</strong></td><td>REQ-DETAIL-PROP</td></tr><tr><td><strong>Prioridad</strong></td><td>Media</td></tr><tr><td><strong>Tipo</strong></td><td>Funcional — Edge Case</td></tr><tr><td><strong>Precondiciones</strong></td><td>Columna <code>{key: &#39;code&#39;, header: &#39;Code&#39;, visible: true, detail: true}</code></td></tr><tr><td><strong>Pasos</strong></td><td>1. Verificar que la columna se renderiza<br>2. Hacer clic en celda clickeable de la misma fila<br>3. Verificar payload</td></tr><tr><td><strong>Resultado Esperado</strong></td><td>La columna se renderiza (por <code>visible: true</code>) Y además aparece en <code>detailData</code> al hacer clic.</td></tr><tr><td><strong>Notas</strong></td><td><code>detail</code> no implica <code>visible: false</code>. Son propiedades ortogonales.</td></tr></tbody></table><hr><h2 id="tc-detail-prop-04-multiples-columnas-detail-con-datos-parciales" tabindex="-1">TC-DETAIL-PROP-04: Múltiples columnas detail con datos parciales <a class="header-anchor" href="#tc-detail-prop-04-multiples-columnas-detail-con-datos-parciales" aria-label="Permalink to &quot;TC-DETAIL-PROP-04: Múltiples columnas detail con datos parciales&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td><strong>ID</strong></td><td>TC-DETAIL-PROP-04</td></tr><tr><td><strong>Requerimiento</strong></td><td>REQ-DETAIL-PROP</td></tr><tr><td><strong>Prioridad</strong></td><td>Media</td></tr><tr><td><strong>Tipo</strong></td><td>Funcional — Edge Case</td></tr><tr><td><strong>Precondiciones</strong></td><td>Columnas detail: <code>[{key: &#39;a&#39;, detail: true}, {key: &#39;b&#39;, detail: true}, {key: &#39;c&#39;, detail: true}]</code>. Fila: <code>{name: &#39;Alice&#39;, a: &#39;A1&#39;, c: &#39;C1&#39;}</code> (falta <code>b</code>).</td></tr><tr><td><strong>Pasos</strong></td><td>1. Hacer clic en celda clickeable<br>2. Verificar payload</td></tr><tr><td><strong>Resultado Esperado</strong></td><td><code>detailData</code> contiene: <code>[{label: &#39;A&#39;, value: &#39;A1&#39;}, {label: &#39;C&#39;, value: &#39;C1&#39;}]</code>. La columna <code>b</code> cuyo valor es <code>undefined</code> se omite o se incluye con <code>value: undefined</code> según definición del contrato.</td></tr></tbody></table>',14)])])}const P=e(o,[["render",i]]);export{m as __pageData,P as default};
